INSERT OR IGNORE INTO products VALUES
 ('cat_r2_acrylic_membrane','Flexible acrylic waterproof coating','Wave Shield','Waterproofing materials','Suitable for thin-coat reinforcement on walls; corners require mesh fabric, and the construction surface must have no standing water.',4.6,214,587,39800,'Returnable if unopened and the packaging is intact'),
 ('cat_r2_polyurethane_membrane','One-component polyurethane waterproof coating','Azure Boat','Waterproofing materials','For continuous floor coating; maintain ventilation until the odor dissipates, and record the substrate moisture content first.',4.5,173,421,52600,'No returns after chemical products are opened'),
 ('cat_r2_waterproof_mortar','Polymer waterproofing mortar','Construction Balance','Substrate materials','For repairing threshold waterstop curbs and pipe-root radii; conduct the flood test only after curing is complete.',4.7,308,902,18600,'Returnable if unopened'),
 ('cat_r2_reinforcement_fabric','Alkali-resistant waterproof reinforcing mesh','Fabric reinforcement','Auxiliary waterproofing materials','Cover internal and external corners and repair joints; document the overlap width with photos in the construction record.',4.4,126,350,6900,'No returns after cutting'),
 ('cat_r2_corner_tape','Butyl rubber internal/external corner reinforcement tape','Sealant Workshop','Auxiliary waterproofing materials','For pre-treatment at wall-floor junctions; remove loose dust and compact the edges before bonding.',4.5,197,611,12800,'Returnable if unopened'),
 ('cat_r2_pipe_collar','Flexible waterproof collar for pipe penetrations','Water Boundary','Auxiliary waterproofing materials','Collar for pipe roots passing through floor slabs; must match the pipe diameter and have continuous edge finishing.',4.6,142,389,15800,'Exchange available for an unused item with the wrong specification'),
 ('cat_r2_threshold_stop','Stainless-steel threshold waterproof strip','Boundary Bank','Waterproofing construction','Forms a continuous water barrier at the embedded threshold base; check the end closures after installation.',4.8,89,204,23600,'No returns after custom-length cutting'),
 ('cat_r2_absorbent_primer','High-penetration substrate bonding agent','Surface fixing','Substrate materials','Reduces differences in substrate absorption; after application, confirm the timing of the next process according to ambient humidity.',4.3,251,780,11200,'Returnable if unopened'),
 ('cat_r2_moisture_meter','Pin-type substrate moisture meter','Balance Point','Inspection tools','For multipoint measurement before waterproofing, putty, and carpentry; record locations and readings for later review.',4.7,438,1190,32800,'After power-on, returns are allowed only for quality issues'),
 ('cat_r2_coating_gauge','Wet-film thickness gauge','Coating Measurement','Inspection tools','Spot-check coating thickness on every coat; avoid inferring film compliance from quantity used alone.',4.5,96,228,7800,'Returnable if unused'),
 ('cat_r2_test_plug','Drainage-pipe flood-test plug','Water inspection','Inspection tools','Seal the floor drain and drainage branch pipe; before testing, verify the pressure range and sealing-ring condition.',4.6,324,915,4600,'No returns after sanitary products are opened'),
 ('cat_r2_level_ruler','Transparent water-level ruler','Project record','Inspection tools','During the flood test, take water-level readings at the same fixed point at the start and end, and retain evidence simultaneously with the downstairs ceiling inspection.',4.4,117,306,3600,'Returnable if unused'),
 ('cat_r2_tile_adhesive_c2te','Flexible tile adhesive C2TE','DeGu reinforcement','Tiling materials','Suitable for wet-area wall and floor tiles; open time and resting time must be adjusted according to on-site temperature and humidity.',4.8,702,1940,22800,'Returnable if unopened'),
 ('cat_r2_tile_adhesive_fast','Fast-setting tile repair adhesive','Secure tiling','Tiling materials','For small-area repairs; cannot replace large-area substrate leveling or waterproofing-layer repair.',4.2,85,191,9800,'Returnable if unopened'),
 ('cat_r2_epoxy_grout','Two-component mildew-resistant epoxy grout','Seam Research','Grouting materials','Suitable for shower-area joints; after color matching is confirmed, retain leftover material by batch for subsequent repairs.',4.6,389,1055,26800,'No returns after color matching'),
 ('cat_r2_cement_grout','Low-water-absorption cement-based grout','Tile Companion','Grouting materials','For areas not subject to long-term immersion; cure as instructed after construction and check for powdering.',4.3,276,742,9600,'Returnable if unopened'),
 ('cat_r2_leveling_clip','Removable tile leveling system','Flat Laying','Tiling tools','Controls height differences between adjacent tile faces; avoid impacting completed tile edges during removal.',4.5,531,1602,5200,'No returns after consumables are opened'),
 ('cat_r2_tile_spacer','Cross-shaped tile spacer','Flush joint','Tiling tools','For uniform wet-area tile joints; joint width must comply with the requirements of the joint-filling material.',4.4,644,2105,2800,'No returns after consumables are opened'),
 ('cat_r2_notched_trowel','Stainless-steel notched trowel','Craftsman''s Ruler','Tiling tools','Select the notch depth according to the tile-back dimensions; keep the troweling direction consistent to reduce hollowing.',4.7,238,683,8800,'No returns after use'),
 ('cat_r2_rubber_float','Rubber grout float','Seam Craftsman','Tiling tools','Compact the joint filler and clean excess material from the surface; separately recheck fullness at corners.',4.3,154,402,7200,'No returns after use'),
 ('cat_r2_deepseal_drain','Deep-water-seal odor-proof floor drain','Submarine','Water supply and drainage','Compatible with common drain-pipe diameters; confirm the finished-surface height and trap conditions before installation.',4.8,1196,3870,14900,'No returns after installation'),
 ('cat_r2_linear_drain','Narrow-edge linear floor drain','Drainage line','Water supply and drainage','For one-way slope formation in the shower area; the length and outlet position must coordinate with the tile layout.',4.6,205,477,42800,'No returns for custom-length items'),
 ('cat_r2_washer_drain','Washing-machine overflow-prevention floor drain','Water and plumbing safety','Water supply and drainage','Includes dedicated connectors and an overflow channel; verify drainage speed and hose securing.',4.5,412,1268,16800,'No returns after installation'),
 ('cat_r2_ptrap','Serviceable P-trap','Pipe Sequence','Water supply and drainage','The basin drain forms a water seal; leave removal space in the inspection-opening direction.',4.4,188,556,11800,'No returns after installation'),
 ('cat_r2_angle_valve','Ceramic-cartridge angle valve','Valve Safety','Water supply and drainage','Mark hot- and cold-water locations separately; perform a static-pressure check after installation and record any leakage.',4.7,832,2695,6800,'No returns after installation'),
 ('cat_r2_braided_hose','Stainless-steel braided water-supply hose','Connected Water','Water supply and drainage','For connections to basins and toilets; leave sufficient service allowance and do not kink the hose.',4.5,936,3188,4900,'No returns after installation'),
 ('cat_r2_drain_pipe','PVC-U drainage pipes and fittings','Connected Plastics','Water supply and drainage','For branch-pipe modifications; accept after socket bonding based on slope and ball-pass results.',4.8,1502,4890,13800,'No returns after cutting'),
 ('cat_r2_cleanout_cap','Drainage access port with sealing ring','Pipe inspection','Water supply and drainage','Install at an accessible location; photograph and record the orientation and elevation before enclosure.',4.3,104,271,7600,'No returns after installation'),
 ('cat_r2_rcd','Double-pole residual-current circuit breaker 30mA','CHINT','Electrical materials','For the bathroom''s dedicated circuit; test the operating current and disconnection time after installation.',4.9,1284,4021,13600,'After power-on, returns are allowed only for quality issues'),
 ('cat_r2_equipotential_box','Local equipotential bonding terminal box','Delixi','Electrical materials','Bond metal pipes and conductive components; photograph connection points and wire gauges before concealment.',4.7,347,980,9800,'No returns after installation'),
 ('cat_r2_wire_25','Flame-retardant copper-core wire 2.5 mm²','Far East','Electrical materials','For lighting and standard outlet circuits; retain records of the full-roll batch and meter markings.',4.8,2180,7065,23600,'No returns after cutting'),
 ('cat_r2_wire_40','Flame-retardant copper-core wire 4 mm²','Double Superior','Electrical materials','For high-load bathroom-equipment circuits; verify ampacity and the protective device according to the design.',4.8,1765,5312,38800,'No returns after cutting'),
 ('cat_r2_conduit','Flame-retardant electrical conduit 20mm','China Wealth','Electrical materials','Bend radius and fixing intervals should facilitate wire replacement; complete conduit-through inspection before closing.',4.6,940,2874,12800,'No returns after cutting'),
 ('cat_r2_junction_box','Moisture-resistant junction box IP55','Electrical shaft','Electrical materials','For wet-area equipment connections; both box-cover sealing and maintenance accessibility must be accepted.',4.5,283,706,8600,'No returns after installation'),
 ('cat_r2_socket_cover','Splash-proof outlet protective cover','Bull','Electrical materials','Install in locations where splashing may occur; must match the outlet panel and wall flatness.',4.7,1068,3481,5900,'No returns after installation'),
 ('cat_r2_exhaust_fan','Quiet exhaust fan','Panasonic','Ventilation equipment','Select airflow according to bathroom volume; confirm the backflow damper and duct connection on site.',4.8,637,1820,36800,'After installation, returns are allowed only for quality issues'),
 ('cat_r2_heater_fan','Heating, ventilation, and lighting combination unit','AUPU','Ventilation equipment','Ceiling openings, power circuits, and exhaust routes must be jointly rechecked before closing the boards.',4.7,521,1460,128000,'After installation, returns are allowed only for quality issues'),
 ('cat_r2_mirror_light','Moisture-resistant mirror-front light','NVC','Lighting equipment','The light fixture''s ingress-protection rating must match the mirrored cabinet dimensions; power connectors must not be exposed in wet areas.',4.5,364,1011,24800,'After installation, returns are allowed only for quality issues'),
 ('cat_r2_grab_bar_short','Short slip-resistant grab bar','Safety Assistance','Older-adult safety aids','The installation point must fall within an accepted substrate reinforcement area; perform a pull-force recheck after completion.',4.8,244,596,32800,'No returns after installation'),
 ('cat_r2_grab_bar_long','L-shaped corner grab bar','Health support','Older-adult safety aids','Cover the toilet and standing-up path; when positioning, account for the user''s height and door-leaf clearance.',4.7,181,438,56800,'No returns after installation'),
 ('cat_r2_backer_board','Grab-bar backing reinforcement board','Secure Support','Substrate materials','Before closing the wall, secure it to the studs or solid wall, and photograph and mark the dimensions and bolt locations.',4.6,129,315,21800,'No returns after cutting'),
 ('cat_r2_antislip_tile','R10 slip-resistant floor tile','Steady Step','Ceramic Tile','For shower and toilet areas; when selecting tiles, also verify water absorption, batch, and color difference.',4.7,488,1290,6800,'No returns after installation'),
 ('cat_r2_neutral_silicone','Neutral weather-resistant sealant','Baiyun','Sealing materials','For finishing around basins and door sets; clean the gap before construction and allow the required curing time.',4.6,903,3010,4600,'No returns after opening'),
 ('cat_r2_mildew_sealant','Mildew-resistant silicone sealant for kitchens and bathrooms','Wacker','Sealing materials','For joints subject to long-term dampness; do not immediately rinse with water or cover with cleaning agents after caulking.',4.8,722,2168,12800,'No returns after opening'),
 ('cat_r2_backer_rod','Closed-cell foam joint filler rod','Joint bottom','Auxiliary sealing materials','Control the thickness of sealant in deep joints and avoid three-sided adhesion; the diameter should be slightly greater than the joint width.',4.4,118,286,3200,'No returns after cutting'),
 ('cat_r2_floor_film','Thickened floor finished-surface protection film','Site protection','Finished-surface protection','Cover passageways and completed floors; turn the joints outward to prevent grit from entering.',4.5,577,1705,9800,'No returns after cutting'),
 ('cat_r2_corner_guard','Reusable external-corner protective strip','Corner Protection','Finished-surface protection','Protects door casings and wall corners from moving damage; check for tape residue before removal.',4.3,209,608,7600,'No returns after use'),
 ('cat_r2_dust_curtain','Magnetic dustproof isolation door curtain','Clean boundary','Finished-surface protection','Separate the work area from the living area, seal the edges, and provide self-closing functionality after personnel pass through.',4.6,338,929,16800,'No returns after use'),
 ('cat_r2_waste_bag','Thickened woven bags for construction waste','With waste removal','Debris-removal consumables','Bag debris and sharp objects separately; keep each bag within the property management handling requirements.',4.5,765,2408,3900,'No returns after consumables are opened'),
 ('cat_r2_hepa_clean','Post-completion HEPA detailed cleaning service','Clean Home','Cleaning service','Covers high-level dust removal, cabinet interiors, and floor-drain cleaning; do not use fragrance masking agents before air testing.',4.7,93,171,88000,'Rescheduling available before service begins');

