-- REMEDIATION_20260730_PROJECT_SITE_AND_CATALOG_CONTEXT
BEGIN;
UPDATE addresses
SET province='Shanghai', city='Shanghai', district='Xuhui District, Shanghai', detail='No. 233, Tianlin Road, 1808', postal_code='200233'
WHERE address_id='addr_r2bth_1';
UPDATE products SET title='Grab-bar backing reinforcement package (premium)', brand='Anlan aging-in-place renovation auxiliary materials', category='Substrate materials', description='Includes a reinforcement board, corrosion-resistant fasteners, and a location identification card; record the dimensions and load-bearing locations before closing the wall.' WHERE product_id='bnd_r2bth_a1';
UPDATE products SET title='Grab-bar backing reinforcement package (standard)', brand='Anlan aging-in-place renovation auxiliary materials', category='Substrate materials', description='Suitable for reinforcing a single-sided grab-bar substrate; recheck wall conditions and the older adult''s gripping height before installation.' WHERE product_id='bnd_r2bth_a2';
UPDATE products SET title='Grab-bar backing reinforcement package (partial)', brand='Anlan aging-in-place renovation auxiliary materials', category='Substrate materials', description='For local reinforcement at confirmed locations; the area must be enclosed only after concealed work acceptance.' WHERE product_id='bnd_r2bth_a3';
UPDATE products SET title='Flood test and slope reinspection kit', brand='Heng''an inspection tools', category='Inspection tools', description='Includes a water-level ruler, slope gauge, and location record card for joint review of flood testing and floor-drain slope.' WHERE product_id='bnd_r2bth_b1';
UPDATE products SET title='Residual-current protection and equipotential bonding test kit', brand='Heng''an inspection tools', category='Inspection tools', description='For recording residual-current protection operation, circuit insulation, and equipotential bonding status; testing must be performed by a licensed person.' WHERE product_id='bnd_r2bth_b2';
